function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function load(){const r=await apiFetch('/operacoes/admin/conteudo');document.getElementById('rows').innerHTML=r.length?r.map(x=>`<tr><td>${esc(x.titulo)}</td><td>${esc(x.categoria||'—')}</td><td>${esc(x.estado)}</td><td><button onclick="toggle(${x.id},'${x.estado}')">${x.estado==='publicado'?'Arquivar':'Publicar'}</button> <button onclick="delPost(${x.id})">Apagar</button></td></tr>`).join(''):'<tr><td colspan="4">Não existem artigos.</td></tr>'}document.getElementById('criar').onclick=async()=>{try{await apiFetch('/operacoes/admin/conteudo',{method:'POST',body:JSON.stringify({titulo:titulo.value,categoria:categoria.value,estado:estado.value,corpo:corpo.value,imagemUrl:imagem.value})});msg.textContent='Artigo criado.';titulo.value='';corpo.value='';load()}catch(e){msg.textContent=e.message}};async function toggle(id,state){try{await apiFetch('/operacoes/admin/conteudo/'+id,{method:'PUT',body:JSON.stringify({estado:state==='publicado'?'arquivado':'publicado'})});load()}catch(e){alert(e.message)}}async function delPost(id){if(!confirm('Apagar artigo?'))return;try{await apiFetch('/operacoes/admin/conteudo/'+id,{method:'DELETE'});load()}catch(e){alert(e.message)}}load().catch(e=>msg.textContent=e.message);
